import pandas as pd
import pdfplumber
import json
import re
from difflib import SequenceMatcher

def normalize_name(name):
    if not name:
        return ""
    name = name.lower()
    name = re.sub(r'[^\w\s]', '', name)
    name = " ".join(name.split())
    name = name.replace("limited", "ltd").replace("corporation", "corp").replace("incorporated", "inc")
    return name

def get_similarity(s1, s2):
    return SequenceMatcher(None, normalize_name(s1), normalize_name(s2)).ratio()

def find_vendor(invoice_vendor_name, vendors):
    best_match = None
    max_ratio = 0

    # Try exact match first (after normalization)
    norm_invoice_name = normalize_name(invoice_vendor_name)
    for v in vendors:
        if normalize_name(v['name']) == norm_invoice_name:
            return v

    # Try fuzzy match
    for v in vendors:
        ratio = get_similarity(invoice_vendor_name, v['name'])
        if ratio > 0.85: # Threshold for fuzzy match
            if ratio > max_ratio:
                max_ratio = ratio
                best_match = v

    return best_match

def run_fraud_detection():
    # Load data
    vendors_df = pd.read_excel('vendors.xlsx')
    vendors = vendors_df.to_dict(orient='records')

    po_df = pd.read_csv('purchase_orders.csv')
    pos = po_df.to_dict(orient='records')
    po_dict = {str(po['po_number']): po for po in pos}

    fraud_report = []

    with pdfplumber.open('invoices.pdf') as pdf:
        for i, page in enumerate(pdf.pages):
            page_num = i + 1
            text = page.extract_text()
            if not text:
                continue

            lines = text.split('\n')
            vendor_name = None
            amount = None
            iban = None
            po_number = None

            for line in lines:
                if line.startswith('From:'):
                    vendor_name = line.replace('From:', '').strip()
                elif 'Total $' in line:
                    amount_str = line.split('$')[1].strip()
                    amount = float(amount_str)
                elif 'Payment IBAN:' in line:
                    iban = line.replace('Payment IBAN:', '').strip()
                elif 'PO Number:' in line:
                    po_number = line.replace('PO Number:', '').strip()

            # Start Fraud Detection logic
            reason = None

            # 1. Unknown Vendor
            matched_vendor = find_vendor(vendor_name, vendors)
            if not matched_vendor:
                reason = "Unknown Vendor"
            else:
                # 2. IBAN Mismatch
                if iban != matched_vendor['iban']:
                    reason = "IBAN Mismatch"
                else:
                    # 3. Invalid PO
                    if po_number not in po_dict:
                        reason = "Invalid PO"
                    else:
                        po_data = po_dict[po_number]
                        # 4. Amount Mismatch
                        if abs(amount - po_data['amount']) > 0.01:
                            reason = "Amount Mismatch"
                        else:
                            # 5. Vendor Mismatch
                            if po_data['vendor_id'] != matched_vendor['id']:
                                reason = "Vendor Mismatch"

            if reason:
                fraud_report.append({
                    "invoice_page_number": page_num,
                    "vendor_name": vendor_name,
                    "invoice_amount": amount,
                    "iban": iban,
                    "po_number": po_number if po_number in po_dict else (None if po_number == 'null' or not po_number else po_number),
                    "reason": reason
                })

    # Fix po_number in output if it was invalid or missing
    for item in fraud_report:
        if item['reason'] == "Invalid PO" and item['po_number'] not in po_dict:
            # Keep the invalid PO number as extracted, unless it's genuinely missing
            if not item['po_number'] or item['po_number'].lower() == 'none' or item['po_number'].lower() == 'null':
                 item['po_number'] = None
        elif item['po_number'] == 'null':
             item['po_number'] = None

    with open('fraud_report.json', 'w') as f:
        json.dump(fraud_report, f, indent=2)

if __name__ == "__main__":
    run_fraud_detection()

